function getRegionFromProvince(province){
  var r = PROVINCE_REGION[province];
  if(!r) return 'LUZON'; // default fallback
  return r;
}

// Map region group to rate column key
function regionToRateKey(regionGroup){
  var map = { NCR:'ncr', LUZON:'luzon', VISAYAS:'visayas', MINDANAO:'mindanao', ISLAND:'island' };
  return map[regionGroup] || 'luzon';
}

window.onProvinceChange = function(){
  var sel = document.getElementById('co-province');
  var label = document.getElementById('co-shipping-region-label');
  if(!sel||!sel.value) return;
  var province = sel.value;
  var region = getRegionFromProvince(province);
  var rateLabels = { NCR:'Metro Manila rate', LUZON:'Luzon rate', VISAYAS:'Visayas rate', MINDANAO:'Mindanao rate', ISLAND:'Island/Remote rate' };
  if(label) label.textContent = rateLabels[region]||'';
  updateCheckoutTotals();
};

// ─── J&T EXPRESS RATE TABLE ───────────────────────────────────────────────────
// Rates per region based on weight
// J&T rate table — [maxKg, NCR, Luzon, Visayas, Mindanao, Island]
var JT_BRACKETS = [
  [0.5,  85,  95,  100, 105, 115],
  [1,   155, 165,  180, 195, 205],
  [3,   180, 190,  200, 220, 230],
  [4,   270, 280,  300, 330, 340],
  [5,   360, 370,  400, 440, 450],
  [6,   455, 465,  500, 550, 560],
];
var JT_COL = { ncr:0, luzon:1, visayas:2, mindanao:3, island:4 };

function getJTShippingFee(weightKg, rateKey){
  var col = (JT_COL[rateKey] !== undefined) ? JT_COL[rateKey] : JT_COL.luzon;
  for(var i=0;i<JT_BRACKETS.length;i++){
    if(weightKg <= JT_BRACKETS[i][0]) return JT_BRACKETS[i][col+1];
  }
  var last = JT_BRACKETS[JT_BRACKETS.length-1];
  return last[col+1] + Math.ceil(weightKg-6) * 50;
}

function getShippingFee(subtotal){
  // Always read from state.storeSettings (updated by loadStoreSettings/saveStoreSettings)
  // Fall back to FREE_SHIPPING_THRESHOLD local var if not set
  var threshold = FREE_SHIPPING_THRESHOLD;
  if(state.storeSettings && state.storeSettings.freeThreshold != null){
    threshold = Number(state.storeSettings.freeThreshold);
  }
  if(subtotal >= threshold) return 0;
  // Get province → region → rate key
  var provEl = document.getElementById('co-province');
  var province = provEl ? provEl.value : '';
  // If no province selected yet, show NCR rate as default estimate
  var regionGroup = province ? getRegionFromProvince(province) : 'NCR';
  var rateKey = regionToRateKey(regionGroup);
  // Estimate weight from cart
  var totalWeight = 0;
  (state.cart||[]).forEach(function(ci){
    var prod = state.products.find(function(p){ return p.id===ci.id; });
    var prodWeight = 0.1; // default 100g per item
    // Priority 1: variant-level weight field (most accurate)
    if(prod && ci.variant){
      var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null,weight:null};});
      var matchedVariant=variants.find(function(v){ return (v.label||'').trim().toLowerCase()===(ci.variant||'').trim().toLowerCase(); });
      if(matchedVariant && matchedVariant.weight!=null && matchedVariant.weight>0){
        prodWeight = Number(matchedVariant.weight);
      } else {
        // Priority 2: parse weight from variant label text (e.g. "30g", "100g", "1kg")
        var vm = String(ci.variant).match(/(\d+(?:\.\d+)?)(g|kg)/i);
        if(vm){ prodWeight = vm[2].toLowerCase()==='kg' ? parseFloat(vm[1]) : parseFloat(vm[1])/1000; }
        // Priority 3: product-level weight as fallback
        else if(prod.weight) prodWeight = Number(prod.weight);
      }
    } else if(prod && prod.weight){
      // Priority 3: product-level weight (no variant selected)
      prodWeight = Number(prod.weight);
    }
    totalWeight += prodWeight * ci.qty;
  });
  if(totalWeight <= 0) totalWeight = 0.5;
  return getJTShippingFee(totalWeight, rateKey);
}

function updateCheckoutTotals(){
  var isLalamove = state.selectedCourier === 'lalamove';
  var subtotal = state.cart.reduce(function(s,i){ return s+(i.price*i.qty); },0);
  var discount = 0;
  var discountRow = document.getElementById('co-discount-row');
  if(state.appliedDiscount){
    var dc = state.appliedDiscount;
    discount = dc.type==='percent' ? Math.round(subtotal*dc.value/100) : dc.value;
    discount = Math.min(discount, subtotal);
    if(discountRow){ 
      discountRow.style.display='flex';
      document.getElementById('co-discount-label').textContent = dc.code;
      document.getElementById('co-discount-amt').textContent = '-₱'+discount.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
    }
  } else {
    if(discountRow) discountRow.style.display='none';
  }
  // For Lalamove, customer pays delivery directly — no shipping fee on our end
  var shipping = isLalamove ? 0 : getShippingFee(subtotal);
  var total = Math.max(0, subtotal - discount + shipping);
  var subEl = document.getElementById('co-subtotal');
  var totEl = document.getElementById('co-total');
  var shipEl = document.getElementById('co-shipping-amt');
  var shipRow = document.getElementById('co-shipping-row');
  if(subEl) subEl.textContent = '₱'+subtotal.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(totEl) totEl.textContent = '₱'+total.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(shipRow){
    if(isLalamove){
      shipRow.style.display = 'none'; // Lalamove: hide shipping row entirely
    } else {
      shipRow.style.display = 'flex';
      if(shipEl){
        if(shipping === 0){
          shipEl.textContent = 'FREE 🎉';
          shipEl.style.color = '#16a34a';
        } else {
          shipEl.textContent = '₱'+shipping.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
          shipEl.style.color = 'var(--text)';
        }
      }
    }
  }
  state._lastShipping = shipping;
  return total;
}
function updatePromoStrip(){
  var active=state.promos.filter(p=>p.active);
  var t=document.getElementById('promo-track');
  if(!t) return;
  if(!active.length){ t.innerHTML='<span></span>'; return; }
  // Build content with safe text (promo text is admin-controlled but escape anyway)
  function esc(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  var txt=active.map(p=>esc(p.text)).join('   ');
  var doubled=txt+'   '+txt;
  t.innerHTML='<span>'+doubled+'</span>';
}

// ─── STATS ────────────────────────────────────────────────────────────────────
var LOW_STOCK_THRESHOLD = 5;

var _dashPeriodDays=0;
window.setDashPeriod=function(days,btn){ _dashPeriodDays=days; document.querySelectorAll('.period-tab').forEach(function(b){b.classList.remove('active');}); if(btn)btn.classList.add('active'); updateStats(); };
function getFilteredOrders(){ if(!_dashPeriodDays)return state.orders; var c=Date.now()-_dashPeriodDays*86400000; return state.orders.filter(function(o){ var ts=o.createdAt?(o.createdAt.seconds?o.createdAt.seconds*1000:o.createdAt):0; return ts>=c; }); }
function updateStats(){
  var orders=getFilteredOrders();
  var periodLabel=_dashPeriodDays?'Last '+_dashPeriodDays+' days':'All time';
  var ro=orders.filter(function(o){return o.status!=='Cancelled';});
  var revenue=ro.reduce(function(s,o){return s+Number(o.total||o.amount||0);},0);
  var delivered=orders.filter(function(o){return o.status==='Delivered';}).length;
  var cancelled=orders.filter(function(o){return o.status==='Cancelled';}).length;
  var pending=orders.filter(function(o){return o.status==='Processing'||o.status==='Packed';}).length;
  var aov=ro.length?revenue/ro.length:0;
  var retail=state.products.filter(function(p){return p.category==='retail';}).length;
  var ws=state.products.filter(function(p){return p.category==='wholesale';}).length;
  function el(id){return document.getElementById(id);}
  if(el('stat-revenue'))    el('stat-revenue').textContent='₱'+revenue.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(el('stat-revenue-sub'))el('stat-revenue-sub').textContent=periodLabel;
  if(el('stat-orders'))     el('stat-orders').textContent=orders.length;
  if(el('stat-orders-sub')) el('stat-orders-sub').textContent=periodLabel;
  if(el('stat-aov'))        el('stat-aov').textContent='₱'+aov.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(el('stat-pending'))    el('stat-pending').textContent=pending;
  if(el('stat-delivered'))  el('stat-delivered').textContent=delivered;
  if(el('stat-cancelled'))  el('stat-cancelled').textContent=cancelled;
  if(el('stat-total'))      el('stat-total').textContent=state.products.length;
  if(el('stat-retail'))     el('stat-retail').textContent=retail;
  if(el('stat-wholesale'))  el('stat-wholesale').textContent=ws;
  if(el('stat-promo'))      el('stat-promo').textContent=state.promos.filter(function(p){return p.active;}).length;
  renderLowStockWarning();
  renderRevenueChart(orders);
  renderStatusChart(orders);
  renderTopProducts(orders);
}
function renderRevenueChart(orders){
  var canvas=document.getElementById('revenue-chart'); var empty=document.getElementById('revenue-chart-empty'); var label=document.getElementById('revenue-chart-label');
  if(!canvas)return; var days=_dashPeriodDays||30; var now=Date.now(); var buckets=[];
  for(var i=days-1;i>=0;i--){var d=new Date(now-i*86400000);buckets.push({label:(d.getMonth()+1)+'/'+(d.getDate()),value:0,date:d.toDateString()});}
  orders.filter(function(o){return o.status!=='Cancelled';}).forEach(function(o){ var ts=o.createdAt?(o.createdAt.seconds?o.createdAt.seconds*1000:Number(o.createdAt)):0; if(!ts)return; var bkt=buckets.find(function(b){return b.date===new Date(ts).toDateString();}); if(bkt)bkt.value+=Number(o.total||o.amount||0); });
  var hasData=buckets.some(function(b){return b.value>0;}); if(empty)empty.style.display=hasData?'none':'flex'; if(!hasData)return; if(label)label.textContent=_dashPeriodDays?'Last '+_dashPeriodDays+' days':'Last 30 days';
  var ctx=canvas.getContext('2d'); var dpr=window.devicePixelRatio||1; var W=canvas.parentElement.clientWidth||400,H=180;
  canvas.width=W*dpr;canvas.height=H*dpr;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.scale(dpr,dpr);
  var pad={top:16,right:16,bottom:32,left:56}; var cw=W-pad.left-pad.right,ch=H-pad.top-pad.bottom;
  var maxVal=Math.max.apply(null,buckets.map(function(b){return b.value;}))||1;
  ctx.strokeStyle='rgba(0,0,0,0.06)';ctx.lineWidth=1;
  for(var g=0;g<=4;g++){var gy=pad.top+ch-(g/4)*ch;ctx.beginPath();ctx.moveTo(pad.left,gy);ctx.lineTo(pad.left+cw,gy);ctx.stroke();ctx.fillStyle='#9a9890';ctx.font='10px DM Sans,sans-serif';ctx.textAlign='right';var gv=maxVal*g/4;ctx.fillText('₱'+(gv>=1000?(gv/1000).toFixed(1)+'k':gv.toFixed(0)),pad.left-6,gy+3);}
  var grad=ctx.createLinearGradient(0,pad.top,0,pad.top+ch);grad.addColorStop(0,'rgba(74,103,65,0.18)');grad.addColorStop(1,'rgba(74,103,65,0.01)');
  ctx.beginPath();buckets.forEach(function(b,i){var x=pad.left+(i/(buckets.length-1||1))*cw,y=pad.top+ch-(b.value/maxVal)*ch;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});
  ctx.lineTo(pad.left+cw,pad.top+ch);ctx.lineTo(pad.left,pad.top+ch);ctx.closePath();ctx.fillStyle=grad;ctx.fill();
  ctx.beginPath();ctx.strokeStyle='#4a6741';ctx.lineWidth=2;ctx.lineJoin='round';
  buckets.forEach(function(b,i){var x=pad.left+(i/(buckets.length-1||1))*cw,y=pad.top+ch-(b.value/maxVal)*ch;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();
  var step=Math.ceil(buckets.length/7);ctx.fillStyle='#9a9890';ctx.font='10px DM Sans,sans-serif';ctx.textAlign='center';
  buckets.forEach(function(b,i){if(i%step!==0&&i!==buckets.length-1)return;ctx.fillText(b.label,pad.left+(i/(buckets.length-1||1))*cw,H-8);});
}
function renderStatusChart(orders){
  var canvas=document.getElementById('status-chart');var legend=document.getElementById('status-legend');if(!canvas||!orders.length)return;
  var statuses=['Pending','Processing','Packed','Shipped','Delivered','Cancelled'];
  var colors=['#e8a838','#4a6741','#6b8f61','#2563eb','#16a34a','#e24b4a'];
  var counts=statuses.map(function(s){return orders.filter(function(o){return o.status===s;}).length;});
  var total=counts.reduce(function(a,b){return a+b;},0)||1;
  var dpr=window.devicePixelRatio||1,SIZE=140;canvas.width=SIZE*dpr;canvas.height=SIZE*dpr;canvas.style.width=SIZE+'px';canvas.style.height=SIZE+'px';
  var ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);var cx=SIZE/2,cy=SIZE/2,R=54,r=32,angle=-Math.PI/2;
  counts.forEach(function(c,i){if(!c)return;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,R,angle,angle+(c/total)*Math.PI*2);ctx.closePath();ctx.fillStyle=colors[i];ctx.fill();angle+=(c/total)*Math.PI*2;});
  ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();
  ctx.fillStyle='#2d2d28';ctx.font='bold 18px DM Sans,sans-serif';ctx.textAlign='center';ctx.fillText(total,cx,cy+2);ctx.font='10px DM Sans,sans-serif';ctx.fillStyle='#9a9890';ctx.fillText('orders',cx,cy+14);
  if(legend)legend.innerHTML=statuses.map(function(s,i){if(!counts[i])return'';return'<div class="donut-legend-item"><span class="donut-legend-dot" style="background:'+colors[i]+'"></span><span class="donut-legend-label">'+s+'</span><span class="donut-legend-val">'+counts[i]+' ('+Math.round(counts[i]/total*100)+'%)</span></div>';}).join('');
}
function renderTopProducts(orders){
  var el=document.getElementById('top-products-list');if(!el)return;var map={};
  orders.filter(function(o){return o.status!=='Cancelled'&&o.items;}).forEach(function(o){(o.items||[]).forEach(function(item){var k=item.name||'Unknown';if(!map[k])map[k]={name:k,qty:0,revenue:0};map[k].qty+=Number(item.qty||1);map[k].revenue+=Number(item.price||0)*Number(item.qty||1);});});
  var sorted=Object.values(map).sort(function(a,b){return b.revenue-a.revenue;}).slice(0,5);
  if(!sorted.length){el.innerHTML='<div class="top-list-empty">No sales data yet</div>';return;}
  var maxRev=sorted[0].revenue||1;
  el.innerHTML=sorted.map(function(p,i){return'<div class="top-list-item"><div class="top-list-rank">'+(i+1)+'</div><div class="top-list-body"><div class="top-list-name">'+p.name+'</div><div class="top-list-bar-wrap"><div class="top-list-bar" style="width:'+Math.round(p.revenue/maxRev*100)+'%"></div></div></div><div class="top-list-rev">₱'+p.revenue.toLocaleString('en-PH',{minimumFractionDigits:0,maximumFractionDigits:0})+'</div></div>';}).join('');
}

function renderLowStockWarning(){
  var el = document.getElementById('low-stock-warning');
  if(!el) return;
  // Build flat list of {name, label, stock} for all product+variant combos
  var alerts=[];
  state.products.filter(function(p){ return p.category==='retail'; }).forEach(function(p){
    var variants=(p.variants||[]).map(function(v){ return typeof v==='object'?v:{label:v,price:null,stock:null}; });
    var hasVariantStock=variants.some(function(v){ return v.stock!=null&&v.stock!==''; });
    if(hasVariantStock){
      variants.forEach(function(v){
        if(v.stock!=null&&v.stock!==''){
          alerts.push({name:p.name, label:v.label, stock:Number(v.stock)});
        }
      });
    } else if(p.stock!=null&&p.stock!==''){
      alerts.push({name:p.name, label:null, stock:Number(p.stock)});
    }
  });
  var oos=alerts.filter(function(a){ return a.stock<=0; });
  var lowStock=alerts.filter(function(a){ return a.stock>0&&a.stock<=LOW_STOCK_THRESHOLD; });
  if(!oos.length&&!lowStock.length){ el.style.display='none'; return; }
  var html='<div style="font-weight:600;margin-bottom:.5rem;font-size:13px;color:#92400e">⚠️ Stock Alerts</div>';
  if(oos.length){
    html+='<div style="margin-bottom:.4rem;font-size:12px"><strong style="color:#dc2626">Out of Stock:</strong> ';
    html+=oos.map(function(a){
      var lbl=a.label?a.name+' — '+a.label:a.name;
      return '<span style="background:#fef2f2;border:1px solid #fca5a5;border-radius:3px;padding:1px 6px;margin:0 2px;font-size:11px">'+lbl+'</span>';
    }).join('');
    html+='</div>';
  }
  if(lowStock.length){
    html+='<div style="font-size:12px"><strong style="color:#d97706">Low Stock (≤'+LOW_STOCK_THRESHOLD+'):</strong> ';
    html+=lowStock.map(function(a){
      var lbl=a.label?a.name+' — '+a.label:a.name;
      return '<span style="background:#fffbeb;border:1px solid #fcd34d;border-radius:3px;padding:1px 6px;margin:0 2px;font-size:11px">'+lbl+' ('+a.stock+' left)</span>';
    }).join('');
    html+='</div>';
  }
  el.innerHTML=html;
  el.style.display='block';
}

