function renderOverviewOrders(){
  document.getElementById('overview-loading').style.display='none';
  var recent=state.orders.slice(0,5);
  document.getElementById('overview-orders').innerHTML=recent.length
    ? recent.map(function(o){
        return '<tr><td>'+esc(o.ref||o.id)+'</td><td>'+esc(o.email)+'</td><td>₱'+Number(o.total||o.amount||0).toLocaleString()+'</td>'
          +'<td><span class="badge badge-'+((o.status||'pending').toLowerCase())+'">'+( o.status||'Pending')+'</span></td></tr>';
      }).join('')
    : '<tr><td colspan="4" style="text-align:center;color:var(--text-muted);padding:1.5rem">No orders yet.</td></tr>';
}


// ─── ARCHIVE SYSTEM ───────────────────────────────────────────────────────────
// Archive state: track which view is active per table
var _archiveView = { orders: 'active', inquiries: 'active', quotations: 'active' };

// Auto-archive rules: { status -> days after completion }
var AUTO_ARCHIVE_RULES = {
  orders:     { statuses: ['Delivered','Cancelled'], days: 7 },
  inquiries:  { statuses: ['Rejected'],              days: 14 },
  quotations: { statuses: ['Accepted','Declined'],   days: 14 },
};

function isAutoArchived(item, tableId) {
  var rule = AUTO_ARCHIVE_RULES[tableId];
  if (!rule) return false;
  // Manually archived always counts
  if (item.archived) return true;
  // Check auto-archive: completed status + past the delay
  if (rule.statuses.indexOf(item.status) === -1) return false;
  var updatedAt = item.archivedAt || item.updatedAt || item.createdAt;
  if (!updatedAt || !updatedAt.seconds) return false;
  var msElapsed = Date.now() - updatedAt.seconds * 1000;
  var msThreshold = rule.days * 24 * 60 * 60 * 1000;
  return msElapsed >= msThreshold;
}

window.switchArchiveTab = function(tableId, view) {
  _archiveView[tableId] = view;
  // Update tab styles
  var activeTab = document.getElementById(tableId+'-tab-active');
  var archiveTab = document.getElementById(tableId+'-tab-archive');
  var banner = document.getElementById(tableId+'-archive-banner');
  if (activeTab) activeTab.classList.toggle('active', view==='active');
  if (archiveTab) archiveTab.classList.toggle('active', view==='archive');
  if (banner) banner.style.display = view==='archive' ? 'flex' : 'none';
  // Re-render
  if (tableId==='orders') renderOrders(state.searchFilter||'', state.statusFilter||'');
  else if (tableId==='inquiries') renderInquiries(state.inqFilter||'', state.inqStatusFilter||'');
  else if (tableId==='quotations') renderQuotations(state.qtFilter||'', state.qtStatusFilter||'');
};

window.archiveItem = async function(tableId, id) {
  var colName = tableId;
  try {
    await updateDoc(doc(db, colName, id), { archived: true, archivedAt: { seconds: Math.floor(Date.now()/1000) } });
    toast('Archived ✓');
  } catch(e) { toast('Archive failed'); }
};

window.unarchiveItem = async function(tableId, id) {
  var colName = tableId;
  try {
    await updateDoc(doc(db, colName, id), { archived: false, archivedAt: null });
    toast('Restored to active ✓');
  } catch(e) { toast('Restore failed'); }
};

function updateArchiveCounts(tableId, items) {
  var active = items.filter(function(i){ return !isAutoArchived(i, tableId); }).length;
  var archived = items.filter(function(i){ return isAutoArchived(i, tableId); }).length;
  var elA = document.getElementById(tableId+'-count-active');
  var elB = document.getElementById(tableId+'-count-archive');
  if (elA) elA.textContent = active;
  if (elB) elB.textContent = archived;
}

// ─── ORDER TABLE (dashboard) ──────────────────────────────────────────────────
// ─── PAGINATION HELPER ────────────────────────────────────────────────────────
var _pg = {};
var PG_SIZE = 5;
function pgGet(tableId){ return _pg[tableId]||1; }
function pgSet(tableId,page){ _pg[tableId]=page; }
function renderPagination(tableId, total){
  var pages = Math.ceil(total/PG_SIZE)||1;
  var cur = Math.min(pgGet(tableId), pages);
  pgSet(tableId, cur);
  var el = document.getElementById(tableId+'-pagination');
  if(!el) return;
  if(total===0){ el.style.display='none'; return; }
  el.style.display='flex';
  var start=(cur-1)*PG_SIZE+1, end=Math.min(cur*PG_SIZE,total);
  var pgBtns='';
  var range=[];
  if(pages<=7){for(var i=1;i<=pages;i++) range.push(i);}
  else{
    range.push(1);
    if(cur>3) range.push('…');
    for(var i=Math.max(2,cur-1);i<=Math.min(pages-1,cur+1);i++) range.push(i);
    if(cur<pages-2) range.push('…');
    range.push(pages);
  }
  range.forEach(function(r){
    if(r==='…') pgBtns+='<span style="padding:0 4px;color:var(--text-muted);font-size:12px">…</span>';
    else pgBtns+='<button class="pg-btn'+(r===cur?' active':'')+'" onclick="pgGo(\''+tableId+'\','+r+')">'+r+'</button>';
  });
  el.innerHTML='<span class="pagination-info">Showing '+start+'–'+end+' of '+total+'</span>'
    +'<div class="pagination-btns">'
    +'<button class="pg-btn" onclick="pgGo(\''+tableId+'\','+(cur-1)+')" '+(cur===1?'disabled':'')+'>‹ Prev</button>'
    +pgBtns
    +'<button class="pg-btn" onclick="pgGo(\''+tableId+'\','+(cur+1)+')" '+(cur===pages?'disabled':'')+'>Next ›</button>'
    +'</div>';
}
window.pgGo = function(tableId, page){
  pgSet(tableId, page);
  if(tableId==='orders') renderOrders(state.searchFilter||'', state.statusFilter||'');
  else if(tableId==='inquiries') renderInquiries(state.inqFilter||'', state.inqStatusFilter||'');
  else if(tableId==='quotations') renderQuotations(state.qtFilter||'', state.qtStatusFilter||'');
  else if(tableId==='products') renderProductTable(state.searchFilter||'');
};

function renderOrders(filter, statusFilter){
  if((filter||'')!==state.searchFilter||(statusFilter||'')!==state.statusFilter) pgSet('orders',1);
  state.searchFilter=filter||'';
  state.statusFilter=statusFilter||'';
  var isArchiveView = _archiveView['orders']==='archive';
  updateArchiveCounts('orders', state.orders);
  var list=state.orders.filter(function(o){
    var inArchive = isAutoArchived(o, 'orders');
    if(isArchiveView !== inArchive) return false;
    var q=!filter||((o.id||'').toLowerCase().includes(filter.toLowerCase())||(o.email||'').toLowerCase().includes(filter.toLowerCase())||(o.customer||'').toLowerCase().includes(filter.toLowerCase())||(o.ref||'').toLowerCase().includes(filter.toLowerCase()));
    var s=!statusFilter||o.status===statusFilter;
    return q&&s;
  });
  var page=pgGet('orders');
  var pages=Math.ceil(list.length/PG_SIZE)||1;
  if(page>pages){ pgSet('orders',1); page=1; }
  var slice=list.slice((page-1)*PG_SIZE, page*PG_SIZE);
  document.getElementById('orders-tbody').innerHTML=slice.length
    ? slice.map(function(o){
        var _proofImgs=o.proofURLs&&o.proofURLs.length?o.proofURLs:(o.proofURL?[o.proofURL]:[]);
        var proofCell=_proofImgs.length
          ?'<td data-label="Proof" style="position:relative"><img src="'+_proofImgs[0]+'" onclick="showProofLightbox(\''+o.id+'\')" style="width:44px;height:44px;object-fit:cover;border-radius:4px;cursor:pointer;border:1px solid var(--border)" title="Click to view all screenshots">'+(_proofImgs.length>1?'<span style="position:absolute;top:2px;right:2px;background:#3d5a3e;color:#fff;font-size:9px;font-weight:700;border-radius:8px;padding:1px 4px">'+_proofImgs.length+'</span>':'')+'</td>'
          :'<td data-label="Proof" style="color:var(--text-muted);font-size:12px">—</td>';
        return '<tr>'
          +'<td><strong>'+esc(o.ref||o.id)+'</strong><br><span style="font-size:11px;color:var(--stone)">'+esc(o.customer||'')+'</span><br><span style="font-size:11px;color:var(--text-muted)">'+esc(o.email||'')+'</span></td>'
          +'<td data-label="Amount">₱'+Number(o.total||o.amount||0).toLocaleString()+'</td>'
          +'<td data-label="Status"><select onchange="updateStatus(\''+o.id+'\',this.value)" style="border:1px solid var(--border);padding:4px 8px;border-radius:3px;font-size:12px">'
          +(function(){
            var isLalamove = (o.shippingMethod||o.courier||'').toLowerCase().includes('lalamove');
            var opts = isLalamove
              ? ['Pending','Packed','Request Pickup','Delivered','Cancelled']
              : ['Pending','Processing','Packed','Shipped','Delivered','Cancelled'];
            return opts.map(function(s){ return '<option'+(s===o.status?' selected':'')+'>'+s+'</option>'; }).join('');
          })()
          +'</select></td>'
          +proofCell
          +'<td data-label="Tracking"><input placeholder="Tracking #" value="'+(o.tracking||'')+'" style="border:1px solid var(--border);padding:4px 8px;border-radius:3px;font-size:12px;width:110px" onchange="updateTracking(\''+o.id+'\',this.value)"></td>'
          +'<td data-label="Courier"><input placeholder="Courier" value="'+(o.courier||'')+'" style="border:1px solid var(--border);padding:4px 8px;border-radius:3px;font-size:12px;width:90px" onchange="updateCourier(\''+o.id+'\',this.value)"></td>'
          +(function(){
            if(!o.lastNotifiedStatus) return '<td data-label="Notified" style="color:var(--text-muted);font-size:12px;text-align:center">—</td>';
            if(o.lastNotifyOk===false) return '<td data-label="Notified"><span style="font-size:11px;font-weight:600;color:#c0392b;background:#fdecea;padding:2px 7px;border-radius:10px;white-space:nowrap">Email Error</span></td>';
            return '<td data-label="Notified"><span style="font-size:11px;font-weight:600;color:#2d6a4f;background:#d8f3dc;padding:2px 7px;border-radius:10px;white-space:nowrap">'+esc(o.lastNotifiedStatus)+'</span></td>';
          })()
          +'<td style="white-space:nowrap">'
          +'<button class="btn-sm" onclick="viewOrderDetails(\''+o.id+'\')" style="margin-right:4px">📋 Details</button>'
          +'<button class="btn-sm" onclick="sendNotify(\''+o.id+'\')">📧 Notify</button>'
          +(isArchiveView
            ?'<button class="btn-unarchive" onclick="unarchiveItem(\'orders\',\''+o.id+'\')">↩ Restore</button>'
            +'</td>'
            :'<button class="btn-archive" onclick="archiveItem(\'orders\',\''+o.id+'\')">Archive</button>'
            +'</td>'
          )
          +'</tr>';
      }).join('')
    : '<tr><td colspan="8" style="text-align:center;color:var(--text-muted);padding:2rem">No orders found.</td></tr>';
  renderPagination('orders', list.length);
}

// ─── ORDER CRUD ───────────────────────────────────────────────────────────────
// ─── STOCK HELPERS ─────────────────────────────────────────────────────────────
// Deduct stock immediately on order creation
async function deductOrderStock(order){
  if(!order.items||!order.items.length) return;
  if(order.type==='wholesale-manual') return;
  var batch = writeBatch(db);
  var hasWrites = false;
  for(var i=0;i<order.items.length;i++){
    var item=order.items[i];
    var prod=(item.productId&&state.products.find(function(p){return p.id===item.productId;}))
      ||state.products.find(function(p){return (p.name||'').trim().toLowerCase()===(item.name||'').trim().toLowerCase();});
    if(!prod||!prod.id) continue;
    var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
    var hasVarStock=variants.some(function(v){return v.stock!=null&&v.stock!=='';});
    var ivc=(item.variant||'').trim().toLowerCase();
    if(hasVarStock&&item.variant){
      var upd=variants.map(function(v){
        var vc=(v.label||'').trim().toLowerCase();
        return (vc===ivc&&v.stock!=null)?Object.assign({},v,{stock:Math.max(0,Number(v.stock)-Number(item.qty))}):v;
      });
      batch.update(doc(db,'products',prod.id),{variants:upd});
      prod.variants=upd;
      hasWrites=true;
    } else if(!hasVarStock&&prod.stock!==undefined&&prod.stock!==null){
      var ns=Math.max(0,Number(prod.stock)-Number(item.qty));
      batch.update(doc(db,'products',prod.id),{stock:ns});
      prod.stock=ns;
      hasWrites=true;
    }
  }
  if(hasWrites) await batch.commit();
}

// Restore stock when an order is cancelled
async function restoreOrderStock(order){
  if(!order.items||!order.items.length) return;
  if(order.type==='wholesale-manual') return;
  if(order.stockRestored) return; // guard against double-restore
  // Note: we always restore regardless of stockDeducted flag
  // because stock is deducted at checkout for all orders
  var batch = writeBatch(db);
  var hasWrites = false;
  for(var i=0;i<order.items.length;i++){
    var item=order.items[i];
    var prod=(item.productId&&state.products.find(function(p){return p.id===item.productId;}))
      ||state.products.find(function(p){return (p.name||'').trim().toLowerCase()===(item.name||'').trim().toLowerCase();});
    if(!prod||!prod.id) continue;
    var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
    var hasVarStock=variants.some(function(v){return v.stock!=null&&v.stock!=='';});
    var ivc=(item.variant||'').trim().toLowerCase();
    if(hasVarStock&&item.variant){
      var upd=variants.map(function(v){
        var vc=(v.label||'').trim().toLowerCase();
        return (vc===ivc&&v.stock!=null)?Object.assign({},v,{stock:Number(v.stock)+Number(item.qty)}):v;
      });
      batch.update(doc(db,'products',prod.id),{variants:upd});
      prod.variants=upd;
      hasWrites=true;
    } else if(!hasVarStock&&prod.stock!==undefined&&prod.stock!==null){
      batch.update(doc(db,'products',prod.id),{stock:Number(prod.stock)+Number(item.qty)});
      prod.stock=Number(prod.stock)+Number(item.qty);
      hasWrites=true;
    }
  }
  if(hasWrites) await batch.commit();
}

window.updateStatus = async function(id, val){
  try{ requireAuth(); }catch(e){ toast('Admin access required.'); return; }
  try{
    await updateDoc(doc(db,'orders',id), {status:val, updatedAt:serverTimestamp()});
    toast('Status updated → '+val);
    // Send pickup details email when Lalamove order is ready for pickup
    var order = state.orders.find(function(o){ return o.id===id; });
    if(order){
      if(val === 'Request Pickup'){
        // Send pickup details email to customer (address kept private until now)
        if(typeof sendPickupEmail === 'function'){
          try{ await sendPickupEmail(Object.assign({}, order, {status: val})); toast('📦 Pickup details sent to '+order.email); }
          catch(e){ console.warn('Pickup email failed:', e.message); }
        }
      }
      // Restore stock if order is cancelled
      if(val === 'Cancelled'){
        await restoreOrderStock(order);
        await updateDoc(doc(db,'orders',id),{stockRestored:true});
        toast('♻️ Stock restored from cancelled order');
      }
    }
  }catch(e){toast('Error: '+e.message);}
};
// ─── VIEW ORDER DETAILS (admin modal) ────────────────────────────────────────
window.manualDeductStock = async function(id){
  var order = state.orders.find(function(o){ return o.id===id; });
  if(!order){ toast('Order not found'); return; }
  if(order.stockDeducted){ toast('Stock already deducted for this order'); return; }
  var deductErrors = [];
  for(var i=0; i<(order.items||[]).length; i++){
    var item = order.items[i];
    var prod = (item.productId && state.products.find(function(p){ return p.id===item.productId; }))
            || state.products.find(function(p){ return p.name===item.name; })
            || state.products.find(function(p){ return p.name.trim().toLowerCase()===(item.name||'').trim().toLowerCase(); });
    if(prod && prod.id){
      var variants=(prod.variants||[]).map(function(v){ return typeof v==='object'?v:{label:v,price:null,stock:null}; });
      var hasVariantStock=variants.some(function(v){ return v.stock!=null&&v.stock!==''; });
      var itemVariantClean=(item.variant||'').trim().toLowerCase();
      if(hasVariantStock && item.variant){
        var updatedVariants=variants.map(function(v){
          if((v.label||'').trim().toLowerCase()===itemVariantClean && v.stock!=null){
            return Object.assign({},v,{stock:Math.max(0,Number(v.stock)-Number(item.qty))});
          }
          return v;
        });
        try{
          await updateDoc(doc(db,'products',prod.id),{variants:updatedVariants});
          prod.variants=updatedVariants;
        }catch(e){ deductErrors.push(item.name+' ('+item.variant+'): '+e.message); }
      } else if(prod.stock!==undefined && prod.stock!==null){
        var newStock=Math.max(0,Number(prod.stock)-Number(item.qty));
        try{
          await updateDoc(doc(db,'products',prod.id),{stock:newStock});
          prod.stock=newStock;
        }catch(e){ deductErrors.push(item.name+': '+e.message); }
      }
    } else {
      deductErrors.push((item.name||'unknown')+': product not found in inventory');
    }
  }
  await updateDoc(doc(db,'orders',id),{stockDeducted:true});
  // Close and reopen modal to refresh
  var ov = document.getElementById('order-detail-modal-overlay');
  if(ov) ov.remove();
  if(deductErrors.length){ toast('⚠️ Some items failed: '+deductErrors.join(', ')); }
  else { toast('✅ Stock deducted successfully'); }
};

