window.deleteOrder = async function(id){
  try{ requireAuth(); }catch(e){ toast('Admin access required.'); return; }
  var o = state.orders.find(function(x){ return x.id===id; });
  if(!o) return;
  var ref = o.ref || o.id;
  var typed = prompt('To permanently delete this order, type the order reference below:\n\n' + ref);
  if(typed === null) return;
  if(typed.trim() !== ref){ toast('❌ Reference did not match. Order not deleted.'); return; }
  try{
    await deleteDoc(doc(db,'orders',id));
    state.orders = state.orders.filter(function(x){ return x.id!==id; });
    var ov = document.getElementById('order-detail-modal-overlay');
    if(ov) ov.remove();
    renderOrders(state.searchFilter||'', state.statusFilter||'');
    toast('Order deleted');
  }catch(e){ toast('Error: '+e.message); }
};

window.updateTracking = async function(id,val){
  try{ await updateDoc(doc(db,'orders',id),{tracking:val}); toast('Tracking saved ✅'); }
  catch(e){ toast('❌ Save failed: '+e.message); }
};
window.updateCourier = async function(id,val){
  try{ await updateDoc(doc(db,'orders',id),{courier:val}); }
  catch(e){ toast('❌ Save failed: '+e.message); }
};
window.showProofLightbox = function(orderId){
  var order=state.orders.find(o=>o.id===orderId);
  var imgs=order&&order.proofURLs&&order.proofURLs.length?order.proofURLs:(order&&order.proofURL?[order.proofURL]:[]);
  if(!imgs.length) return;
  var inner=document.getElementById('proof-lightbox-inner');
  if(inner){
    inner.innerHTML='<div style="color:rgba(255,255,255,0.6);font-size:12px">Click anywhere to close</div>'
      +imgs.map(function(src,i){
        return '<img src="'+src+'" style="max-width:88vw;max-height:80vh;object-fit:contain;border-radius:8px;box-shadow:0 4px 24px rgba(0,0,0,0.5)">'
          +(imgs.length>1?'<div style="color:rgba(255,255,255,0.45);font-size:11px;text-align:center">Screenshot '+(i+1)+' of '+imgs.length+'</div>':'');
      }).join('');
  }
  document.getElementById('proof-lightbox').style.display='flex';
};

window.sendNotify = async function(id){
  var order = state.orders.find(o=>o.id===id);
  if(!order){ toast('Order not found'); return; }
  if(!resendReady()){ toast('⚠️ Resend API key not configured yet'); return; }

  async function markNotified(ok){
    var fields = { lastNotifiedStatus: order.status, lastNotifyOk: ok };
    try{ await updateDoc(doc(db,'orders',id), fields); }catch(_){}
    Object.assign(order, fields);
    renderOrders(state.searchFilter||'', state.statusFilter||'');
  }

  try{
    var isLalamove = (order.shippingMethod||order.courier||'').toLowerCase().includes('lalamove');
    if(isLalamove && order.status === 'Request Pickup'){
      await sendPickupEmail(order);
    } else {
      await sendCustomerEmail(order);
    }
    await markNotified(true);
    toast('✅ Notified: '+order.status+' — email sent to '+order.email);
  } catch(e){
    console.error('Email error:', e);
    // CORS / network error means the API call was blocked by the browser.
    // Resend must be called from a backend/server, not directly from the browser.
    var isCors = e instanceof TypeError && /fetch|network|CORS/i.test(e.message);
    if(isCors || e.message==='Failed to fetch'){
      // Fallback: open a pre-filled mailto so the admin can send manually
      var statusEmoji = order.status==='Delivered'?'✅':order.status==='Shipped'?'🚚':order.status==='Cancelled'?'❌':'📦';
      var subject = encodeURIComponent(statusEmoji+' Your Zen & Sip Order — '+(order.ref||order.id));
      var body = encodeURIComponent(
        'Hi '+(order.customer||'there')+',\n\n'
        +'Your order '+(order.ref||order.id)+' is now: '+order.status+'.\n'
        +(order.tracking?'Tracking #: '+order.tracking+(order.courier?' via '+order.courier:'')+'\n':'')
        +'\nThank you for shopping with Zen & Sip!\n— The Zen & Sip Team'
      );
      window.open('mailto:'+order.email+'?subject='+subject+'&body='+body);
      await markNotified(true);
      toast('⚠️ Notified: '+order.status+' (via mailto — direct email blocked by browser)');
    } else {
      await markNotified(false);
      toast('❌ Email failed: '+(e.message||'Unknown error'));
    }
  }
};

// ─── TRACKING (customer-facing) ───────────────────────────────────────────────
var statusSteps=['Processing','Packed','Shipped','Delivered'];
window.trackOrder = async function(){
  var email=document.getElementById('track-email').value.trim().toLowerCase();
  var oid=document.getElementById('track-order').value.trim().toUpperCase();
  if(!email||!oid){alert('Please enter both email and order reference.');return;}
  var btn=document.querySelector('[onclick="trackOrder()"]');
  if(btn){btn.textContent='Searching...';btn.disabled=true;}
  var order=null;
  try{
    // 1. Try local state first (fast, no index needed)
    order=state.orders.find(function(o){
      var refMatch=(o.ref||'').toUpperCase()===oid;
      var idMatch=(o.id||'').toUpperCase()===oid;
      var emailMatch=(o.email||'').toLowerCase()===email;
      return (refMatch||idMatch)&&emailMatch;
    });
    // 2. Query by ref only (single-field, no composite index), filter email client-side
    if(!order){
      var snap=await getDocs(query(collection(db,'orders'),where('ref','==',oid)));
      snap.docs.forEach(function(d){
        var o=Object.assign({id:d.id},d.data());
        if((o.email||'').toLowerCase()===email) order=o;
      });
    }
    // 3. Full scan fallback (handles old orders without ref field)
    if(!order){
      var snapAll=await getDocs(collection(db,'orders'));
      snapAll.docs.forEach(function(d){
        var o=Object.assign({id:d.id},d.data());
        var refMatch=(o.ref||'').toUpperCase()===oid||(o.id||'').toUpperCase()===oid;
        var emailMatch=(o.email||'').toLowerCase()===email;
        if(refMatch&&emailMatch) order=o;
      });
    }
  }catch(e){
    console.error('Track query error:',e.message);
    if(btn){btn.textContent='Track Order';btn.disabled=false;}
    alert('Something went wrong while searching. Please try again.');
    return;
  }
  if(btn){btn.textContent='Track Order';btn.disabled=false;}
  if(!order){alert('No order found. Please check your email and order reference (e.g. WSO-123456).');return;}
  document.getElementById('track-order-id').textContent=order.ref||order.id;
  var curIdx=statusSteps.indexOf(order.status);
  var statusEmoji={'Pending':'⏳','Processing':'✅','Packed':'📦','Shipped':'🚚','Delivered':'🍵','Cancelled':'❌'};
  var statusDesc={
    'Pending':   'We received your order and are verifying your payment.',
    'Processing':'Your payment is verified! Your order is being prepared.',
    'Packed':    'Your order is packed and waiting for the courier.',
    'Shipped':   'Your order is on its way!',
    'Delivered': 'Your order has been delivered. Enjoy your matcha! 🍵',
    'Cancelled': 'This order has been cancelled.',
  };
  var html='';
  html+='<div style="background:var(--warm-white);border-radius:8px;padding:1rem;margin-bottom:1.2rem;font-size:13px">';
  html+='<div style="color:var(--text-muted)">'+esc(order.email)+'</div>';
  html+='<div style="margin-top:.3rem;font-size:22px;color:var(--matcha);font-family:var(--font-display);font-weight:400">'+(statusEmoji[order.status]||'📋')+' '+order.status+'</div>';
  html+='<div style="margin-top:.3rem;font-size:13px;color:var(--text)">'+(statusDesc[order.status]||'')+'</div>';
  if(order.tracking) html+='<div style="margin-top:.6rem;font-size:13px;padding:.5rem .8rem;background:#fff;border-radius:6px;border:1px solid var(--border)">🚚 <strong>'+(order.courier||'Courier')+'</strong> — Tracking #: <strong>'+order.tracking+'</strong></div>';
  html+='</div>';
  html+='<div class="track-timeline">';
  statusSteps.forEach(function(s,i){
    if(order.status==='Cancelled'&&s!=='Cancelled'&&i>curIdx) return;
    var done=curIdx>=0?i<curIdx:false;
    var active=i===curIdx;
    html+='<div class="status-step">'
      +'<div class="status-dot'+(done?' done':'')+(active?' active':'')+'">'+(done?'✓':(active?(statusEmoji[s]||'●'):''))+'</div>'
      +'<div class="status-info"><h4 style="'+(active?'color:var(--matcha)':'')+'">'+s+'</h4>'
      +'<p style="font-size:12px;color:var(--text-muted)">'+(active?statusDesc[s]:'')+(done?'Completed':'')+'</p></div>'
      +'</div>';
  });
  html+='</div>';
  if(order.items&&order.items.length){
    html+='<div style="margin-top:1.2rem;border-top:1px solid var(--border);padding-top:1rem">';
    html+='<div style="font-size:11px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--stone);margin-bottom:.6rem">Items Ordered</div>';
    order.items.forEach(function(it){
      html+='<div style="display:flex;justify-content:space-between;font-size:13px;padding:.3rem 0;border-bottom:1px solid var(--border)"><span>'+it.name+(it.variant?' ('+it.variant+')':'')+'  ×'+it.qty+'</span><span style="font-weight:500">₱'+(it.price*it.qty).toLocaleString()+'</span></div>';
    });
    html+='<div style="display:flex;justify-content:space-between;font-size:14px;font-weight:600;padding:.6rem 0;color:var(--matcha)"><span>Total</span><span>₱'+Number(order.total).toLocaleString()+'</span></div>';
    html+='</div>';
  }
  // Policy notice — no customer cancellation allowed at any stage
  // Only admin can cancel orders from the dashboard
  if(order.status !== 'Cancelled'){
    html+='<div style="margin-top:1.2rem;border-top:1px solid var(--border);padding-top:1rem">';
    html+='<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:.9rem 1rem;font-size:12px;color:#92400e;text-align:center;line-height:1.6">';
    html+='<strong>⚠️ No Refund · No Replacement · No Cancellation</strong><br>';
    html+='All sales are final. Orders cannot be cancelled once placed.';
    html+='</div>';
    html+='</div>';
  }
  document.getElementById('track-content').innerHTML=html;
  document.getElementById('track-overlay').classList.add('open');
};
window.customerCancelOrder = function(){
  // Disabled — cancellations must be handled by admin per store policy
  alert('Orders cannot be cancelled. All sales are final.\nPlease contact us if you have concerns.');
};
window.goToTracking = function(){
  // Navigate to home page
  if(typeof showPage === 'function') showPage('home');
  // Scroll to tracking section after short delay for page render
  setTimeout(function(){
    var trackEl = document.querySelector('.tracking-section');
    if(trackEl){
      trackEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
      // Focus the email input
      var emailEl = document.getElementById('track-email');
      if(emailEl) setTimeout(function(){ emailEl.focus(); }, 400);
    }
  }, 150);
};

window.openTrackModal = function(){
  var overlay = document.getElementById('track-overlay');
  if(!overlay) return;
  overlay.classList.add('open');
  // Reset form
  var emailEl = document.getElementById('track-email');
  var orderEl = document.getElementById('track-order');
  var content = document.getElementById('track-content');
  var titleEl = document.getElementById('track-order-id');
  if(emailEl) emailEl.value = '';
  if(orderEl) orderEl.value = '';
  if(content) content.innerHTML = '';
  if(titleEl) titleEl.textContent = 'Track Your Order';
  // Show form, hide results
  var formWrap = document.getElementById('track-form-wrap');
  if(formWrap) formWrap.style.display = '';
  setTimeout(function(){
    if(emailEl) emailEl.focus();
  }, 150);
};

window.closeTrackModal = function(e){
  if(e.target===document.getElementById('track-overlay'))
    document.getElementById('track-overlay').classList.remove('open');
};

