// ─── MANUAL ORDER PRODUCT SEARCH ─────────────────────────────────────────────
(function(){
  var box;
  function getBox(){
    if(!box){
      box = document.createElement('div');
      box.id = 'mo-prod-suggestions';
      box.style.cssText = 'position:fixed;background:#fff;border:1px solid var(--border);border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,.12);z-index:500;max-height:220px;overflow-y:auto;display:none;min-width:220px';
      document.body.appendChild(box);
    }
    return box;
  }
  document.addEventListener('click', function(e){
    if(box && !box.contains(e.target) && !(e.target.dataset && e.target.dataset.moProdSearch)) box.style.display='none';
  });
  window.moProductSearch = function(idx, inputEl){
    var q = (inputEl.value||'').trim();
    var b = getBox();
    if(q.length < 1){ b.style.display='none'; return; }
    var lower = q.toLowerCase();
    var wsProds = (state.products||[]).filter(function(p){ return p.category==='wholesale'; });
    var suggestions = [];
    wsProds.forEach(function(p){
      if(!(p.name||'').toLowerCase().includes(lower)) return;
      var variants = (p.variants||[]).map(function(v){ return typeof v==='object'?v:{label:v,price:null}; });
      if(variants.length){
        variants.forEach(function(v){
          suggestions.push({ name:p.name, variant:v.label||'', price:v.price!=null?v.price:(p.price||0) });
        });
      } else {
        suggestions.push({ name:p.name, variant:'', price:p.price||0 });
      }
    });
    if(!suggestions.length){ b.style.display='none'; return; }
    var rect = inputEl.getBoundingClientRect();
    b.style.left  = rect.left+'px';
    b.style.top   = (rect.bottom+4)+'px';
    b.style.width = Math.max(rect.width, 260)+'px';
    b._suggestions = suggestions.slice(0,12);
    b.innerHTML = b._suggestions.map(function(s, si){
      var label = esc(s.name)+(s.variant?' <span style="color:var(--stone)">('+esc(s.variant)+')</span>':'');
      return '<div onmousedown="event.preventDefault();moFillProduct('+idx+','+si+')" '
        +'style="padding:.5rem .8rem;cursor:pointer;border-bottom:1px solid var(--border);font-size:13px;display:flex;justify-content:space-between;align-items:center" '
        +'onmouseenter="this.style.background=\'var(--warm-white)\'" onmouseleave="this.style.background=\'\'">'
        +'<span>'+label+'</span>'
        +'<span style="color:var(--matcha);font-weight:600;margin-left:.8rem;white-space:nowrap">&#8369;'+Number(s.price).toLocaleString()+'</span>'
        +'</div>';
    }).join('');
    b.style.display='block';
  };
  window.moFillProduct = function(rowIdx, suggIdx){
    var b = document.getElementById('mo-prod-suggestions');
    var s = b && b._suggestions && b._suggestions[suggIdx];
    if(!s || !_moItems[rowIdx]) return;
    _moItems[rowIdx].name    = s.name;
    _moItems[rowIdx].variant = s.variant;
    _moItems[rowIdx].price   = s.price;
    renderMoItems();
    if(box) box.style.display='none';
    setTimeout(function(){
      var rows = document.querySelectorAll('#mo-items-list > div');
      if(rows[idx]){ var q=rows[idx].querySelectorAll('input')[2]; if(q) q.focus(); }
    }, 0);
  };
})();
var _moItems = []; // [{name,variant,qty,price}]
var _moInvoiceFile = null; // attached PDF/image invoice

// Invoice file picker
window.moPickInvoice = function(){
  var inp = document.getElementById('mo-invoice-input');
  if(inp) inp.click();
};
window.moInvoiceSelected = function(e){
  var file = e.target.files && e.target.files[0];
  if(!file){ _moInvoiceFile=null; renderMoInvoicePreview(); return; }
  var allowed = ['application/pdf','image/jpeg','image/png','image/webp'];
  if(!allowed.includes(file.type)){ toast('Only PDF, JPG, PNG or WEBP allowed'); e.target.value=''; return; }
  if(file.size > 5*1024*1024){ toast('File must be under 5MB'); e.target.value=''; return; }
  _moInvoiceFile = file;
  renderMoInvoicePreview();
};
window.moClearInvoice = function(){
  _moInvoiceFile = null;
  var inp = document.getElementById('mo-invoice-input');
  if(inp) inp.value='';
  renderMoInvoicePreview();
};
function renderMoInvoicePreview(){
  var wrap = document.getElementById('mo-invoice-preview');
  if(!wrap) return;
  if(!_moInvoiceFile){
    wrap.innerHTML = '';
    wrap.style.display = 'none';
    return;
  }
  wrap.style.display = 'flex';
  var icon = _moInvoiceFile.type==='application/pdf' ? '📄' : '🖼️';
  wrap.innerHTML = '<span style="font-size:18px">'+icon+'</span>'
    +'<span style="flex:1;font-size:12px;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+_moInvoiceFile.name+'</span>'
    +'<span style="font-size:11px;color:var(--stone)">'+((_moInvoiceFile.size/1024).toFixed(0))+' KB</span>'
    +'<button onclick="moClearInvoice()" style="background:none;border:none;color:#e24b4a;cursor:pointer;font-size:14px;padding:0 2px" title="Remove">✕</button>';
}

// Read invoice file as base64 for storing in Firestore
function readInvoiceAsBase64(file){
  return new Promise(function(resolve, reject){
    var reader = new FileReader();
    reader.onload = function(e){ resolve(e.target.result); };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

window.addManualOrderItem = function(){
  _moItems.push({name:'',variant:'',qty:1,price:0});
  renderMoItems();
};

window.removeMoItem = function(i){
  _moItems.splice(i,1);
  renderMoItems();
};

window.updateMoItem = function(i, field, val){
  _moItems[i][field] = field==='qty'||field==='price' ? Number(val)||0 : val;
  updateMoTotal();
};

function updateMoTotal(){
  var shippingEl = document.getElementById('mo-shipping');
  var shipping = shippingEl ? (parseFloat(shippingEl.value)||0) : 0;
  var subtotal = _moItems.reduce(function(s,it){ return s + it.price*it.qty; }, 0);
  var total = subtotal + shipping;
  var el = document.getElementById('mo-total-display');
  if(el) el.innerHTML = '<strong>Subtotal:</strong> ₱'+subtotal.toLocaleString()+' &nbsp;|&nbsp; <strong>Shipping:</strong> ₱'+shipping.toLocaleString()+' &nbsp;|&nbsp; <strong>Total:</strong> <span style="color:var(--matcha);font-size:16px;font-weight:700">₱'+total.toLocaleString()+'</span>';
  return total;
}

function renderMoItems(){
  var container = document.getElementById('mo-items-list');
  if(!container) return;
  if(!_moItems.length){
    container.innerHTML = '<div style="color:var(--text-muted);font-size:13px;padding:.5rem 0">No items added yet. Click "+ Add Item" below.</div>';
    updateMoTotal();
    return;
  }
  var hdrs = '<div style="display:grid;grid-template-columns:2fr 1fr 80px 100px 36px;gap:.5rem;margin-bottom:.3rem">'
    + '<div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--stone)">Product Name</div>'
    + '<div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--stone)">Variant</div>'
    + '<div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--stone);text-align:center">Qty</div>'
    + '<div style="font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--stone)">Unit Price (\u20b1)</div>'
    + '<div></div>'
    + '</div>';
  container.innerHTML = hdrs + _moItems.map(function(it,i){
    return '<div style="display:grid;grid-template-columns:2fr 1fr 80px 100px 36px;gap:.5rem;align-items:center;margin-bottom:.5rem">'
      + '<input class="form-input" placeholder="Product name" value="' + it.name + '" data-mo-prod-search="1" oninput="updateMoItem(' + i + ',\'name\',this.value);moProductSearch(' + i + ',this)" onfocus="moProductSearch(' + i + ',this)" autocomplete="off">'
      + '<input class="form-input" placeholder="Variant (opt.)" value="' + it.variant + '" oninput="updateMoItem(' + i + ',\'variant\',this.value)">'
      + '<input class="form-input" type="number" min="1" value="' + it.qty + '" oninput="updateMoItem(' + i + ',\'qty\',this.value)" style="text-align:center" title="Quantity">'
      + '<input class="form-input" type="number" min="0" value="' + it.price + '" oninput="updateMoItem(' + i + ',\'price\',this.value)" title="Unit price">'
      + '<button class="btn-sm danger" onclick="removeMoItem(' + i + ')" style="padding:8px 10px" title="Remove">\u00d7</button>'
      + '</div>';
  }).join('');
  updateMoTotal();
}

// ─── PAYMENT PROOF UPLOAD (customer-facing, via ?pay=ORDERID link) ───────────
window.initPayProofFlow = function(orderId){
  window._payProofRef = new URLSearchParams(window.location.search).get('ref') || '';
  // Remove any existing overlay first to avoid duplicate IDs
  var existing = document.getElementById('pay-proof-overlay');
  if(existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'pay-proof-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:9999;display:flex;align-items:center;justify-content:center;padding:1rem;overflow-y:auto';

  // Already submitted on this device — don't show the form again
  if(localStorage.getItem('zs_proof_'+orderId)){
    overlay.innerHTML =
      '<div style="background:#fff;border-radius:12px;padding:2.5rem 2rem;max-width:380px;width:100%;text-align:center;box-shadow:0 8px 40px rgba(0,0,0,.25)">'
      +'<div style="font-size:52px;margin-bottom:1rem">✅</div>'
      +'<h2 style="color:#2d3a2e;margin:0 0 10px;font-family:Georgia,serif">Already Submitted!</h2>'
      +'<p style="color:#8a8070;font-size:14px;line-height:1.6;margin:0">We already received your payment screenshot. No need to upload again — we\'ll verify it and update your order shortly. 🍵</p>'
      +'</div>';
    document.body.appendChild(overlay);
    return;
  }

  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border-radius:12px;padding:2rem;max-width:400px;width:100%;box-shadow:0 8px 40px rgba(0,0,0,.25)';
  card.innerHTML =
    '<div style="text-align:center;margin-bottom:1.4rem">'
    +'<div style="font-size:32px;margin-bottom:.4rem">💳</div>'
    +'<h2 style="font-size:18px;color:#2d3a2e;margin:0 0 6px;font-family:Georgia,serif">Pay for Your Order</h2>'
    +(window._payProofRef?'<p style="font-size:12px;color:#8a8070;margin:0">Ref: <strong>'+window._payProofRef+'</strong></p>':'')
    +'</div>'
    +'<p style="font-size:13px;color:#5a5a50;margin:0 0 1rem">Choose your payment method:</p>'
    +PAYMENT_METHODS.map(function(m){
      return '<button onclick="payProofSelectMethod(\''+m.id+'\',\''+orderId+'\')" style="display:flex;align-items:center;gap:.8rem;width:100%;background:#fff;border:2px solid #e0d8cc;border-radius:10px;padding:.9rem 1.1rem;cursor:pointer;font-size:14px;font-weight:600;color:#2d3a2e;margin-bottom:.6rem;transition:border-color .15s" onmouseenter="this.style.borderColor=\''+m.color+'\'" onmouseleave="this.style.borderColor=\'#e0d8cc\'">'
        +'<span style="font-size:22px">'+m.logo+'</span>'
        +'<span>'+m.name+'</span>'
        +'</button>';
    }).join('');
  window._payProofCard = card;
  overlay.appendChild(card);
  document.body.appendChild(overlay);
};

