        +'<button onclick="payProofRemove('+i+');event.stopPropagation()" style="position:absolute;top:-5px;right:-5px;background:#e24b4a;color:#fff;border:none;border-radius:50%;width:16px;height:16px;font-size:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1">×</button>'
        +'</div>';
