window.submitManualOrder = async function(sendEmail, triggerBtn){
  try{ requireAuth(); }catch(e){ toast('Please log in first.'); return; }
  var customer = (document.getElementById('mo-customer').value||'').trim();
  var email = (document.getElementById('mo-email').value||'').trim();
  var phone = (document.getElementById('mo-phone').value||'').trim();
  var address = (document.getElementById('mo-address').value||'').trim();
  if(!customer||!email||!phone||!address){ alert('Please fill in all required customer fields.'); return; }
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ alert('Please enter a valid email address.'); return; }
  if(!_moItems.length){ alert('Please add at least one item.'); return; }
  var invalidItems = _moItems.filter(function(it){ return !it.name||it.qty<1||it.price<0; });
  if(invalidItems.length){ alert('Please fill in all item names, quantities, and prices.'); return; }
  var shipping = parseFloat(document.getElementById('mo-shipping').value)||0;
  var subtotal = _moItems.reduce(function(s,it){ return s+it.price*it.qty; },0);
  var total = subtotal + shipping;
  var business = (document.getElementById('mo-business').value||'').trim();
  var notes = (document.getElementById('mo-notes').value||'').trim();
  var status = document.getElementById('mo-status').value;
  var paymentStatus = document.getElementById('mo-payment-status').value;
  var courier = (document.getElementById('mo-courier').value||'jnt');
  var ref = 'WSO-'+Date.now().toString().slice(-6);
  var orderData = {
    customer: customer,
    business: business||'',
    email: email, phone: phone, address: address,
    items: _moItems.map(function(it){ return {name:it.name, variant:it.variant||'', qty:it.qty, price:it.price}; }),
    total: total,
    shipping: shipping,
    ref: ref,
    payment: 'Manual — '+paymentStatus,
    status: status,
    notes: notes||'',
    courier: courier,
    shippingMethod: courier==='lalamove'?'Lalamove':'J&T Express',
    type: 'wholesale-manual',
    createdAt: serverTimestamp(),
  };
  // Attach invoice file as base64 if provided
  if(_moInvoiceFile){
    try{
      orderData.invoiceFile = await readInvoiceAsBase64(_moInvoiceFile);
      orderData.invoiceFileName = _moInvoiceFile.name;
      orderData.invoiceFileType = _moInvoiceFile.type;
    }catch(e){ console.warn('Could not read invoice file:', e); }
  }
  var btn = triggerBtn || null;
  if(btn){ btn.textContent='Saving…'; btn.disabled=true; }
  try{
    var oref = await addDoc(collection(db,'orders'), orderData);
    var orderId = oref.id;
    // Optionally send email
    if(sendEmail && resendReady()){
      try{
        var itemsList = _moItems.map(function(it){
          return '<tr><td style="padding:6px 0;border-bottom:1px solid #f0ebe0">'+it.name+(it.variant?' ('+it.variant+')':'')+'</td>'
            +'<td style="padding:6px 0;border-bottom:1px solid #f0ebe0;text-align:center">x'+it.qty+'</td>'
            +'<td style="padding:6px 0;border-bottom:1px solid #f0ebe0;text-align:right">P'+(it.price*it.qty).toLocaleString()+'</td></tr>';
        }).join('');
        var moAttachments = [];
        var moInvoiceBlock = '';
        if(orderData.invoiceFile){
          var moIsPdf = (orderData.invoiceFileType||'').includes('pdf');
          var moFileName = orderData.invoiceFileName || (moIsPdf ? 'invoice.pdf' : 'invoice.jpg');
          if(moIsPdf){
            moAttachments.push({ filename: moFileName, content: orderData.invoiceFile.replace(/^data:[^;]+;base64,/, '') });
            moInvoiceBlock = '<div style="margin-top:20px;padding:14px 16px;background:#f5f0e8;border-radius:8px;border-left:3px solid #3a5438;font-size:13px;color:#3d3d35">'
              +'<strong>📄 Invoice:</strong> <em>'+moFileName+'</em><br>'
              +'<span style="color:#8a8070">Your invoice is attached as a PDF to this email.</span>'
              +'</div>';
          } else {
            moInvoiceBlock = '<div style="margin-top:20px">'
              +'<div style="font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#8a8070;margin-bottom:8px">Invoice</div>'
              +'<img src="'+orderData.invoiceFile+'" alt="Invoice" style="max-width:100%;border-radius:8px;border:1px solid #e8e0d4;display:block">'
              +'</div>';
          }
        }
        // Payment section — only when payment is still pending
        var moPayBlock = '';
        if(paymentStatus === 'Pending'){
          var payUrl = 'https://zennsip.com/?pay='+orderId+'&ref='+encodeURIComponent(ref);
          moPayBlock = '<div style="margin-top:20px;background:#f0f7ee;border:1px solid #c8d8c5;border-radius:8px;padding:20px;text-align:center">'
            +'<p style="font-size:14px;color:#3d3d35;margin:0 0 6px">Amount to pay: <strong style="font-size:16px;color:#3d5a3e">₱'+total.toLocaleString()+'</strong></p>'
            +'<p style="font-size:13px;color:#8a8070;margin:0 0 16px">Pay via GCash or GoTyme, then tap the button below to upload your screenshot:</p>'
            +'<a href="'+payUrl+'" style="display:inline-block;background:#3a5438;color:#fff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;letter-spacing:.04em">Proceed with Payment →</a>'
            +'</div>';
        }
        var html = emailWrap(
          '<p style="font-size:14px;color:#3d3d35;margin:0 0 6px">Hi <strong>'+customer+'</strong>,</p>'
          +'<h2 style="font-size:20px;color:#2d3a2e;margin:0 0 8px">Order Confirmation</h2>'
          +'<p style="font-size:13px;color:#8a8070;margin:0 0 16px">Reference: <strong>'+ref+'</strong></p>'
          +'<table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:16px">'+itemsList
          +'<tr><td colspan="2" style="padding:8px 0;font-size:13px;color:#8a8070">Shipping</td><td style="padding:8px 0;text-align:right">P'+shipping.toLocaleString()+'</td></tr>'
          +'<tr><td colspan="2" style="padding:8px 0;font-weight:600;font-size:15px">Total</td>'
          +'<td style="padding:8px 0;font-weight:600;font-size:15px;text-align:right;color:#3d5a3e">P'+total.toLocaleString()+'</td></tr>'
          +'</table>'
          +(notes?'<p style="font-size:13px;color:#8a8070">Notes: '+notes+'</p>':'')
          +moInvoiceBlock
          +moPayBlock
        );
        await resendSend(email, 'Order Confirmation '+ref+' — Zen & Sip', html, moAttachments);
        toast('Order saved + email sent ✅');
      }catch(emailErr){
        console.warn('Manual order email failed:', emailErr);
        toast('Order saved ✅ (email failed — check console)');
      }
    } else {
      toast('Manual order saved ✅ — Ref: '+ref);
    }
    clearManualOrderForm();
  }catch(e){ alert('Error saving order: '+e.message); }
  if(btn){ btn.textContent= sendEmail ? 'Save + Send Email' : 'Save Order'; btn.disabled=false; }
};

