// ─── CART ─────────────────────────────────────────────────────────────────────
window.variantBtnClick = function(btn){
  var label = btn.getAttribute('data-label');
  var vp = btn.getAttribute('data-vprice');
  var bp = btn.getAttribute('data-bprice');
  var variantPrice = (vp && vp !== 'null') ? parseFloat(vp) : null;
  var basePrice = parseFloat(bp) || 0;
  selectVariant(btn, label, variantPrice, basePrice);
};
window.selectVariant = function(btn,label,variantPrice,basePrice){
  // Block OOS variant selection entirely
  var p=state.currentProduct;
  if(p && isOOS(p, label)){
    toast('❌ This variant is out of stock.');
    return;
  }
  state.currentQty=1;
  document.getElementById('modal-qty').textContent='1';
  document.querySelectorAll('.variant-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  var displayPrice=variantPrice!=null?variantPrice:basePrice;
  document.getElementById('modal-price').textContent=displayPrice===0?'Contact for Pricing':'\u20b1'+displayPrice.toLocaleString();
  // ✅ Update state.currentVariant so addToCart uses the correct variant
  if(p){
    var variants=(p.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
    var matched = variants.find(function(v){ return v.label===label; });
    state.currentVariant = matched || {label:label, price:variantPrice};
  }
  var vOos=p?isOOS(p,label):false;
  var atcBtn=document.getElementById('modal-atc-btn');
  if(atcBtn){
    if(vOos){
      atcBtn.setAttribute('disabled','');
      atcBtn.textContent='Out of Stock';
      atcBtn.style.cssText='background:#b0b0b0;cursor:not-allowed;opacity:0.6;';
    } else {
      atcBtn.removeAttribute('disabled');
      atcBtn.textContent='Add to Cart';
      atcBtn.style.cssText='';
    }
  }
  updateModalStockIndicator();
};
window.changeQty = function(d){
  var p=state.currentProduct;
  if(!p) return;
  var vLabel=state.currentVariant?state.currentVariant.label:undefined;
  var avail=stockAvailable(p, vLabel);
  var newQty=Math.max(1, state.currentQty+d);
  if(d>0 && newQty>avail){
    toast('Only '+avail+' unit'+(avail===1?'':'s')+' available'+(vLabel?' for '+vLabel:'')+'.'); return;
  }
  state.currentQty=newQty;
  document.getElementById('modal-qty').textContent=state.currentQty;
  updateModalStockIndicator();
};
window.closeModal = function(){document.getElementById('product-overlay').classList.remove('open')};
window.closeProductModal = function(e){if(e.target===document.getElementById('product-overlay'))closeModal()};
window.addToCart = function(){
  var p=state.currentProduct;
  if(!p) return;
  // Require variant selection if product has variants
  var variants=(p.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
  if(variants.length > 0 && !state.currentVariant){
    toast('Please select a variant first.');
    return;
  }
  // Normalise: use undefined (not '') for no-variant products so isOOS/variantStock
  // comparisons are consistent with cart lookups (ci.variant===variantLabel).
  var vLabel=state.currentVariant&&state.currentVariant.label!=null&&state.currentVariant.label!==''
    ? state.currentVariant.label : undefined;
  if(isOOS(p, vLabel)){
    toast('❌ This variant is out of stock.');
    var _atcBtn=document.getElementById('modal-atc-btn');
    if(_atcBtn){ _atcBtn.setAttribute('disabled',''); _atcBtn.textContent='Out of Stock'; _atcBtn.style.cssText='background:#b0b0b0;cursor:not-allowed;opacity:0.6;'; }
    return;
  }
  var variantPrice=state.currentVariant&&state.currentVariant.price!=null?state.currentVariant.price:p.price;
  var avail=stockAvailable(p, vLabel);
  var canAdd=Math.min(state.currentQty, avail===Infinity?state.currentQty:avail);
  if(canAdd<=0){ toast('No more stock available for this item.'); return; }
  if(canAdd<state.currentQty){ toast('Only '+canAdd+' unit'+(canAdd===1?'':'s')+' available. Adding '+canAdd+'.'); }
  // Store undefined (not '') so cart lookups with variant===undefined work correctly
  var cartKey=vLabel; // undefined for no-variant products
  var existing=state.cart.find(function(x){ return x.id===p.id&&x.variant===cartKey; });
  if(existing){ existing.qty+=canAdd; }
  else{ state.cart.push({id:p.id,name:p.name,price:variantPrice,emoji:p.emoji,variant:cartKey,qty:canAdd}); }
  updateCartCount();
  closeModal();
  setTimeout(openCart,200);
};
