window.openCheckout = function(){
  if(!state.cart.length){toast('Your cart is empty!');return;}
  // Block checkout only if actual stock is 0 (not cart-adjusted)
  var oosItems=state.cart.filter(function(ci){
    var prod=state.products.find(function(p){return p.id===ci.id;});
    if(!prod) return false;
    var vLabel=ci.variant||undefined;
    var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
    var hasVStock=variants.some(function(v){return v.stock!=null&&v.stock!=='';});
    if(hasVStock && vLabel){ var s=variantStock(prod,vLabel); return s!==Infinity&&s<=0; }
    return prod.stock!==undefined&&prod.stock!==null&&prod.stock!==''&&Number(prod.stock)<=0;
  });
  if(oosItems.length){
    var names=oosItems.map(function(ci){return '"'+ci.name+'"';}).join(', ');
    toast('⚠️ Remove out-of-stock item'+(oosItems.length>1?'s':'')+': '+names);
    openCart();
    return;
  }
  // reset to step 1
  document.getElementById('checkout-step-1').style.display='block';
  document.getElementById('checkout-step-2').style.display='none';
  document.getElementById('checkout-step-3').style.display='none';
  // Reset courier to J&T (default)
  state.selectedCourier = 'jnt';
  if(typeof selectCourier === 'function') selectCourier('jnt');
  // populate summary
  var items=state.cart.map(function(i){
    return '<div style="display:flex;justify-content:space-between"><span>'+i.name+(i.variant?' <span style="color:var(--stone)">('+i.variant+')</span>':'')+' ×'+i.qty+'</span><span style="font-weight:500">₱'+( i.price*i.qty).toLocaleString()+'</span></div>';
  }).join('');
  document.getElementById('co-items').innerHTML=items;
  // reset discount
  state.appliedDiscount=null;
  var promoInput=document.getElementById('co-promo-input');
  var promoMsg=document.getElementById('co-promo-msg');
  if(promoInput) promoInput.value='';
  if(promoMsg){ promoMsg.style.display='none'; promoMsg.textContent=''; }
  updateCheckoutTotals();
  document.getElementById('checkout-overlay').classList.add('open');
  closeCart();
};
window.closeCheckoutModal = function(e){
  if(e.target===document.getElementById('checkout-overlay'))
    document.getElementById('checkout-overlay').classList.remove('open');
};
window.goToPayment = function(){
  var fname=document.getElementById('co-fname').value.trim();
  var lname=document.getElementById('co-lname').value.trim();
  var email=document.getElementById('co-email').value.trim();
  var phone=document.getElementById('co-phone').value.trim();
  var addr=document.getElementById('co-address').value.trim();
  var province=(document.getElementById('co-province')||{value:''}).value||'';
  var courier = state.selectedCourier || 'jnt';
  // Province required for J&T (for shipping rate calc), optional for Lalamove
  if(!fname||!lname||!email||!phone||!addr||(courier==='jnt'&&!province)){
    alert('Please fill in all fields'+(courier==='jnt'?' including Province':'')+'.');return;
  }
  var regionGroup=getRegionFromProvince(province);
  var phoneClean=phone.replace(/\s+/g,'');
  if(!/^(09|\+639)\d{9}$/.test(phoneClean)){alert('Please enter a valid Philippine mobile number (e.g. 09XX XXX XXXX).');return;}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){alert('Please enter a valid email address.');return;}
  var total=updateCheckoutTotals();
  var ref='WSO-'+Date.now().toString().slice(-6);
  state.checkoutRef=ref;
  state.checkoutCustomer={fname,lname,email,phone,addr,province,total};
  document.getElementById('co-pay-amount').textContent='₱'+total.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
  document.getElementById('co-ref').textContent=ref;
  document.getElementById('co-ref2').textContent=ref;
  // Build payment method selector and reset state
  buildPayMethodGrid();
  state.selectedPayMethod=null;
  document.getElementById('pay-account-box').classList.remove('visible');
  // Reset proof upload UI
  state.proofFiles=[];
  renderProofThumbs();
  document.getElementById('checkout-step-1').style.display='none';
  document.getElementById('checkout-step-2').style.display='block';
  // Re-enable confirm button in case a prior failed attempt left it disabled
  var confirmBtn=document.getElementById('co-confirm-btn');
  if(confirmBtn){ confirmBtn.disabled=false; confirmBtn.textContent='Review & Confirm Order \u2192'; }
};
function renderProofThumbs(){
  var thumbs=document.getElementById('proof-thumbs');
  var ph=document.getElementById('proof-placeholder');
  var ind=document.getElementById('proof-upload-indicator');
  var cnt=document.getElementById('proof-upload-count');
  var zone=document.getElementById('proof-drop-zone');
  if(!thumbs) return;
  var files=state.proofFiles||[];
  if(!files.length){
    thumbs.style.display='none';
    if(ph) ph.style.display='block';
    if(ind) ind.classList.remove('visible');
    if(zone) zone.classList.remove('has-file');
    return;
  }
  thumbs.innerHTML=files.map(function(f,i){
    return '<div style="position:relative;display:inline-block">'
      +'<img src="'+URL.createObjectURL(f)+'" style="width:72px;height:72px;object-fit:cover;border-radius:6px;border:2px solid var(--matcha-muted)">'
      +'<button onclick="removeProofFile('+i+');event.stopPropagation()" style="position:absolute;top:-5px;right:-5px;background:#e24b4a;color:#fff;border:none;border-radius:50%;width:18px;height:18px;font-size:11px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1">×</button>'
      +'</div>';
  }).join('');
  thumbs.style.display='flex';
  if(ph) ph.style.display='none';
  if(ind) ind.classList.add('visible');
  if(cnt) cnt.textContent='✓ '+files.length+' screenshot'+(files.length>1?'s':'')+' ready';
  if(zone) zone.classList.add('has-file');
}
window.removeProofFile=function(i){
  if(!state.proofFiles) return;
  state.proofFiles.splice(i,1);
  renderProofThumbs();
};
window.handleProofUpload = function(input){
  var files=Array.from(input.files||[]);
  if(!files.length) return;
  if(!state.proofFiles) state.proofFiles=[];
  var max=3;
  files.forEach(function(f){
    if(state.proofFiles.length>=max){ toast('Max '+max+' screenshots allowed'); return; }
    state.proofFiles.push(f);
  });
  input.value='';
  renderProofThumbs();
};

