window.confirmPayment = async function(){
  if(!state.selectedPayMethod){alert('Please select a payment method first.');return;}
  if(!state.proofFiles||!state.proofFiles.length){alert('Please upload your payment screenshot first.');return;}
  if(!_rateLimitOk('order', 3)){alert('Too many order attempts. Please wait a moment.');return;}
  var btn=document.getElementById('co-confirm-btn');
  if(!btn){ console.warn('co-confirm-btn not found'); }
  if(btn){ btn.textContent='Verifying…'; btn.disabled=true; }
  // reCAPTCHA v3 check
  try{
    await new Promise(function(resolve, reject){
      grecaptcha.ready(function(){
        grecaptcha.execute('6LdZJt4sAAAAADghH01uYyM_M_wTJbwDzG5Ok_Yx', {action:'checkout'}).then(function(token){
          if(!token){ reject(new Error('reCAPTCHA failed. Please try again.')); return; }
          resolve(token);
        }).catch(reject);
      });
    });
  }catch(e){ if(btn){ btn.textContent='I\'ve Paid — Confirm Order ✓'; btn.disabled=false; } showErrorModal('Security check failed. Please refresh the page and try again.',e.message,'https://zennsip.com/?dash=orders'); return; }
  if(btn) btn.textContent='Saving proof…';
  var c=state.checkoutCustomer;
  // sanitise all customer fields before saving
  c.fname=_sanitise(c.fname); c.lname=_sanitise(c.lname);
  c.email=_sanitise(c.email); c.phone=_sanitise(c.phone);
  c.addr=_sanitise(c.addr);
  try{
    // Compress all proof images
    function compressProofFile(file){
      return new Promise(function(resolve, reject){
        var img=new Image();
        var objectUrl=URL.createObjectURL(file);
        img.onload=function(){
          var MAX=700, w=img.width, h=img.height;
          if(w>h&&w>MAX){h=Math.round(h*MAX/w);w=MAX;}
          else if(h>=w&&h>MAX){w=Math.round(w*MAX/h);h=MAX;}
          var canvas=document.createElement('canvas');
          canvas.width=w; canvas.height=h;
          canvas.getContext('2d').drawImage(img,0,0,w,h);
          URL.revokeObjectURL(objectUrl);
          resolve(canvas.toDataURL('image/jpeg',0.62));
        };
        img.onerror=reject;
        img.src=objectUrl;
      });
    }
    var proofURLs=[];
    for(var pi=0;pi<state.proofFiles.length;pi++){
      proofURLs.push(await compressProofFile(state.proofFiles[pi]));
    }
    var proofBase64=proofURLs[0];

    // Pre-generate order ID (needed by the transaction below)
    var newOrderRef = doc(collection(db,'orders'));

    if(btn) btn.textContent='Saving order…';

    var discountInfo = state.appliedDiscount ? {
      code:  state.appliedDiscount.code,
      type:  state.appliedDiscount.type,
      value: state.appliedDiscount.value,
    } : null;

    // Re-validate promo minimum order at time of checkout submission
    if(state.appliedDiscount && state.appliedDiscount.minOrder){
      var subtotalAtSubmit = state.cart.reduce(function(s,i){ return s+(i.price*i.qty); },0);
      if(subtotalAtSubmit < state.appliedDiscount.minOrder){
        if(btn){ btn.disabled=false; btn.textContent='I\'ve Paid — Confirm Order ✓'; }
        alert('Promo code "'+state.appliedDiscount.code+'" requires a minimum order of ₱'+state.appliedDiscount.minOrder+'. Your cart total does not meet this requirement.');
        state.appliedDiscount=null;
        updateCheckoutTotals();
        return;
      }
    }

    var orderData = {
      customer:c.fname+' '+c.lname,
      email:c.email, phone:c.phone, address:c.addr, province:c.province||'', region:c.province?getRegionFromProvince(c.province):'LUZON',
      items:state.cart.map(i=>({productId:i.id,name:i.name,variant:i.variant||'',qty:i.qty,price:i.price})),
      total:c.total,
      shipping: state._lastShipping || 0,
      shippingMethod: state.selectedCourier || 'jnt',
      courier: state.selectedCourier === 'lalamove' ? 'Lalamove' : 'J&T Express',
      discount: discountInfo,
      ref:state.checkoutRef,
      payment: 'Via '+(state.selectedPayMethod?state.selectedPayMethod.name:'E-Wallet')+' (pending verification)',
      proofURL: proofBase64,
      proofURLs: proofURLs,
      status: 'Pending',
      createdAt:serverTimestamp(),
      stockDeducted: true,
    };

    // Atomic transaction: check live stock, save order, deduct stock in one operation
    await runTransaction(db, async function(transaction){
      // Read current product docs from Firestore (authoritative stock values)
      var productItems = [];
      for(var i=0; i<state.cart.length; i++){
        var ci = state.cart[i];
        var prodRef = doc(db, 'products', ci.id);
        var prodSnap = await transaction.get(prodRef);
        if(prodSnap.exists()) productItems.push({ci:ci, ref:prodRef, data:prodSnap.data()});
      }
      // Validate stock for each item
      for(var j=0; j<productItems.length; j++){
        var ci = productItems[j].ci;
        var prod = productItems[j].data;
        var variants = (prod.variants||[]).map(function(v){ return typeof v==='object'?v:{label:v,price:null,stock:null}; });
        var hasVarStock = variants.some(function(v){ return v.stock!=null&&v.stock!==''; });
        if(hasVarStock && ci.variant){
          var vLabel = (ci.variant||'').trim().toLowerCase();
          var matchedV = variants.find(function(v){ return (v.label||'').trim().toLowerCase()===vLabel; });
          if(matchedV && matchedV.stock!=null && Number(matchedV.stock) < ci.qty){
            throw new Error('"'+ci.name+(ci.variant?' ('+ci.variant+')':'')+'" ran out of stock. Please update your cart.');
          }
        } else if(!hasVarStock && prod.stock!=null && prod.stock!==''){
          if(Number(prod.stock) < ci.qty){
            throw new Error('"'+ci.name+'" ran out of stock. Please update your cart.');
          }
        }
      }
      // Create order doc
      transaction.set(newOrderRef, orderData);
      // Deduct stock atomically
      for(var k=0; k<productItems.length; k++){
        var ci = productItems[k].ci;
        var prod = productItems[k].data;
        var prodRef = productItems[k].ref;
        var variants = (prod.variants||[]).map(function(v){ return typeof v==='object'?v:{label:v,price:null,stock:null}; });
        var hasVarStock = variants.some(function(v){ return v.stock!=null&&v.stock!==''; });
        var vLabel = (ci.variant||'').trim().toLowerCase();
        if(hasVarStock && ci.variant){
          var upd = variants.map(function(v){
            var vc = (v.label||'').trim().toLowerCase();
            return (vc===vLabel&&v.stock!=null) ? Object.assign({},v,{stock:Math.max(0,Number(v.stock)-Number(ci.qty))}) : v;
          });
          transaction.update(prodRef, {variants: upd});
        } else if(!hasVarStock && prod.stock!=null && prod.stock!==''){
          transaction.update(prodRef, {stock: Math.max(0, Number(prod.stock)-Number(ci.qty))});
        }
      }
    });

    // Increment discount code usage count
    if(state.appliedDiscount){
      var dc = state.discountCodes.find(function(d){ return d.id===state.appliedDiscount.id; });
      if(dc) await updateDoc(doc(db,'discount_codes',dc.id),{uses:(dc.uses||0)+1});
      state.appliedDiscount=null;
    }

    // Send emails + push notification (non-blocking — don't fail order if these fail)
    try {
      await sendOwnerEmail({...orderData, ref:state.checkoutRef});
      sendOrderPushNotification({...orderData, ref:state.checkoutRef}); // fire and forget
      // Use Lalamove-specific confirmation email if Lalamove was selected
      if((state.selectedCourier||'') === 'lalamove'){
        await sendLalamoveOrderEmail({...orderData, ref:state.checkoutRef});
      } else {
        await sendCustomerEmail({...orderData, ref:state.checkoutRef});
      }
    } catch(emailErr){ console.warn('Email send failed:', emailErr); }

    document.getElementById('co-final-ref').textContent=state.checkoutRef;
    document.getElementById('checkout-step-2').style.display='none';
    document.getElementById('checkout-step-3').style.display='block';
    state.cart=[];
    state.proofFiles=[];
    updateCartCount();
    renderCart();
  }catch(e){ showErrorModal('We couldn\'t place your order. Please check your internet connection and try again. Your payment has not been charged.',e.message,'https://zennsip.com/?dash=orders'); }
  if(btn){ btn.textContent='I\'ve Paid — Confirm Order ✓'; btn.disabled=false; }
};

function updateCartCount(){
  var total=state.cart.reduce((s,x)=>s+x.qty,0);
  document.getElementById('cart-count').textContent=total;
}
window.openCart = function(){
  document.getElementById('cart-drawer').classList.add('open');
  document.getElementById('drawer-overlay').classList.add('open');
  renderCart();
};
window.closeCart = function(){
  document.getElementById('cart-drawer').classList.remove('open');
  document.getElementById('drawer-overlay').classList.remove('open');
};
function renderCart(){
  var el=document.getElementById('drawer-items');
  if(!state.cart.length){
    el.innerHTML='<div class="empty-cart"><div class="ico">🛒</div><p>Your cart is empty</p></div>';
    document.getElementById('drawer-subtotal').textContent='₱0';
    return;
  }
  el.innerHTML=state.cart.map(function(item,i){
    var prod=state.products.find(function(p){return p.id===item.id;});
    // Check OOS excluding this item's own qty from cart count (it's already in cart)
    // OOS warning = actual stock is 0, not cart-adjusted
    var itemOos=(function(){
      if(!prod) return false;
      var vLabel=item.variant||undefined;
      var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
      var hasVStock=variants.some(function(v){return v.stock!=null&&v.stock!=='';});
      if(hasVStock && vLabel){ var s=variantStock(prod,vLabel); return s!==Infinity&&s<=0; }
      return prod.stock!==undefined&&prod.stock!==null&&prod.stock!==''&&Number(prod.stock)<=0;
    })();
    var oosWarning=itemOos?'<div style="font-size:11px;color:#dc2626;font-weight:600;letter-spacing:0.04em;margin-top:4px">⚠ Out of stock — please remove</div>':'';
    return '<div class="cart-item"'+(itemOos?' style="opacity:.6"':'')+'>'
      +'<div class="cart-item-img"'+(itemOos?' style="filter:grayscale(100%)"':'')+'>'+item.emoji+'</div>'
      +'<div class="cart-item-info">'
      +'<div class="cart-item-name">'+item.name+'</div>'
      +(item.variant?'<div class="cart-item-variant">'+item.variant+'</div>':'')
      +'<div class="cart-item-price">₱'+Number(item.price).toLocaleString()+'</div>'
      +oosWarning
      +'<div class="cart-item-row">'
      +'<div class="qty-sm"><button onclick="cartQty('+i+',-1)">−</button><span>'+item.qty+'</span><button onclick="cartQty('+i+',1)">+</button></div>'
      +'<button class="remove-btn" onclick="removeItem('+i+')">Remove</button>'
      +'</div></div></div>';
  }).join('');
  var sub=state.cart.reduce((s,x)=>s+x.price*x.qty,0);
  document.getElementById('drawer-subtotal').textContent='₱'+sub.toLocaleString();
  // Disable checkout button if any cart item is OOS
  var hasOos=state.cart.some(function(item){
    var prod=state.products.find(function(p){return p.id===item.id;});
    if(!prod) return false;
    // OOS = actual stock is 0, not cart-adjusted
    var vLabel=item.variant||undefined;
    var variants=(prod.variants||[]).map(function(v){return typeof v==='object'?v:{label:v,price:null,stock:null};});
    var hasVStock=variants.some(function(v){return v.stock!=null&&v.stock!=='';});
    if(hasVStock && vLabel){
      var s=variantStock(prod,vLabel);
      return s!==Infinity && s<=0;
    }
    return prod.stock!==undefined&&prod.stock!==null&&prod.stock!==''&&Number(prod.stock)<=0;
  });
  var checkoutBtn=document.getElementById('cart-checkout-btn');
  if(checkoutBtn){
    checkoutBtn.disabled=hasOos;
    checkoutBtn.style.opacity=hasOos?'0.45':'';
    checkoutBtn.style.cursor=hasOos?'not-allowed':'';
    checkoutBtn.title='';
    checkoutBtn.textContent=hasOos?'Remove out-of-stock items first':'Proceed to Checkout →';
  }
  // Re-render product grid only if OOS state may have changed (cart qty changed)
  // Use a debounced flag to avoid re-rendering on every single cart open
  renderShop();
  renderWholesale();
  // Refresh modal stock indicator if product modal is open
  if(document.getElementById('product-overlay').classList.contains('open')){
    updateModalStockIndicator();
  }
}
window.cartQty = function(i,d){
  if(d>0){
    var ci=state.cart[i];
    var prod=state.products.find(function(p){return p.id===ci.id;});
    if(prod){
      var vStock=variantStock(prod, ci.variant);
      var totalInCartForVariant=state.cart.reduce(function(s,x){ return s+(x.id===ci.id&&x.variant===ci.variant?x.qty:0); },0);
      if(vStock!==Infinity && totalInCartForVariant>=vStock){ toast('No more stock available for this variant.'); return; }
    }
  }
  state.cart[i].qty=Math.max(1,state.cart[i].qty+d);
  updateCartCount();
  renderCart();
};
window.removeItem = function(i){state.cart.splice(i,1);updateCartCount();renderCart()};

